(D_MODE, D_BL2, D_CC, D_CB, D_JB, D_JP, D_JS, D_PA, D_CL, D_CROSS, D_COVA, D_JA, D_JAS, D_BC, D_BLN) = (0x1900 + 8 * i for i in range(25, 40))
