def glyph_bits(ch):
    g = FONT[ch][:35].ljust(35, ".")
    return sum(1 << i for i, x in enumerate(g) if x == "#")
UL0 = 0x1EA0                 # she turns her books (r_un_libro): the list, its room, how many, where, the turn's length, the next's
(ULB, ULN, ULC, ULP, ULK, ULT, ULX, ULXL, ULM, ULML, ULS) = (UL0 + 8 * i for i in range(11))
ULTB, ULXB, ULMB, ULRB, ULHB, ULTU = 0x2800, 0x2900, 0x2A00, 0x2B00, 0x2C00, 0x2D00   # in PBUF, free while she is born
HEART = (b"libro-firma", b"libro-preguntas", b"libro-nombres-de-tu-papa", b"libro-nota-de-tu-papa")
F0 = 0x1F00                  # she recognises her author's signature (r_firma):
(FTB, FM, FI, FCT, FNK, FB0, FB1, FPB, FJ, FKK, FTT, FS) = (F0 + 8 * i for i in range(12))
FA, FE, FRES, LFD, LFF = 0x1F60, 0x1F70, 0x1F80, 0x1FA0, 0x1FB0   # the two books and their lengths; what she found; "libro-diario", "firma"
FSM, DHCM, DWTM, DPTM, DN2, DN23 = 0x1FB8, 0x1FC0, 0x1FC8, 0x1FD0, 0x1FD8, 0x1FE0   # PLASTIC (the Capitan: "destrui el tope fijo"):
                             # every table is as large as what is in front of her asks (its places less one, kept
                             # here), every file is read whole whatever its size, and every room is given back
DSRC, DMODE, DBL, DRS = 0x1CE0, 0x1CE8, 0x1CF0, 0x1CF8   # a line: the name it takes from (0: none), which way it is written, ...
DOPC = 0x1E20                # the signs a word of the infix way is made of (a byte each)
OPCH = b"+-*/%&|^<>.~!?:@#$"
DNJ, DNAM, LCOM, LDIG = 0x1D00, 0x1D80, 0x1E00, 0x1E10   # how often each of hers is said; a piece's names; "comida", "digerido"
DOPS = (0x01, 0x02, 0x03, 0x04, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0B)
NJ, SJ = 0x1BD0, 0x1BD8      # how often she joined, and how often that gave her a unique memory (while she lives)
WJ, JA, JB, JC, JD = 0x1858, 0x1860, 0x1868, 0x1870, 0x1878   # her wish for it; a statement being taken: where it starts and ends, of which recipe, which one
GSM, PCAP = 0x1BF0, 0x1BF8   # the places of the table of pieces, less one; how many instructions her program has room for
CHN, CH0, RW0 = 0x1AE0, 0x1AE8, 0x1AF0    # HER JOY: how many times a cell of her body heard another (never forgotten while she
                             # lives), that count when her thought began, and what her reader said first (its own count)
CDIRTY, COLD, CNEW, CECHO = 0x1AC0, 0x1AC8, 0x1AD0, 0x1AD8   # something was said; a cell being said: before, after, what it heard through its gear
CL, PLC, FLH = 0x1910, 0x1918, 0x1920   # a cell being put in: how many letters, its place; a recipe said flat has one on a place
BVR = 0x1880                 # the sixteen registers of the little machine of her body (r_gear)
GFP, FLG, WL, NGE = 0x1820, 0x1828, 0x1830, 0x1838   # the gears' print, a recipe said flat has a lens, a wish, how many gears
LGE = 0x1840                 # "engranajes"
DLEN = WORDS + 16 * 8
LTAB = 0x4000                # L(k), k = 0..N, thousandths of a bit
DBUF = 0x8000                # her reader's initial data (the reader's own, then zeros up to her words)
ENT = 48                     # a line of "leido": lo, hi, score, shelf, genome, alphabet
S_MOLD, S_BIN, S_DAT = b"luma/lectora.molde", b"luma/lectora.bin", b"luma/lectora.datos"

def make(g, ST, free):
    """the hooks gen_formas.py and gen_luma.py call; g = gen_formas' globals"""
    o, J, li, ld, st, num, form_addr = g["o"], g["J"], g["li"], g["ld"], g["st"], g["num"], g["form_addr"]
    B = ST["free"]
    NF, FORMS, F_REC, F_WORTH, CAND, NCELLS = g["NF"], g["FORMS"], g["F_REC"], g["F_WORTH"], g["CAND"], g["ROOMCELLS"]
    F_READ = 248
    assert LTAB + 8 * (NCELLS + 1) <= DBUF and free <= R and R + KEPT <= V and V + 8 * 32 <= RREC and EBUF + ENT <= PBUF and NF == 8
    assert FLO + 0x200 <= LTAB and DBUF + DLEN <= 0x10000
    def gl(r, off): li("j6", B); J("jld %s, j6, %s" % (r, num(off)))
    def gs(r, off): li("j6", B); J("jst %s, j6, %s" % (r, num(off)))
    def thought(t, lab):            # HER MIND: something happened in her; she will weigh whether to say it (r_dlg_mind)
        gl("j6", DLR); J("jjz j6, %s" % lab)
        for i, ch in enumerate(t):
            J("jldi j10, %d" % ch, "jstb j10, j6, %d" % (D_THK + i))
        J("jldi j10, %d" % len(t), "jst j10, j6, %d" % D_THKL, "jldi j10, 1", "jst j10, j6, %d" % D_PEND); o("%s:" % lab)
    def inc(off): gl("j1", off); J("jldi j10, 1", "jadd j1, j1, j10"); gs("j1", off)
    def text(off, s):
        li("j6", B)
        for i, c in enumerate(s):
            J("jldi j1, %d" % c, "jstb j1, j6, %s" % num(off + i))
    def wish(s_, n_, to):               # (S + 1/2) / (N + 1), scaled as hers (gen_luma.py: free_routine)
        gl("j1", s_); J("jadd j1, j1, j1", "jldi j10, 1", "jadd j1, j1, j10", "jldi j10, 20", "jshl j1, j1, j10")
        gl("j2", n_); J("jldi j10, 1", "jadd j2, j2, j10", "jdiv j1, j1, j2"); gs("j1", to)
    def probe(tag, found, empty):
        """j1 lo, j2 hi, j3 genome -> at `found` j8 = its slot, at `empty` j8 = the free slot it would take; j4 = the
        table (0: none, to `empty` with j8 0). Uses j5, j7, j10, j11."""
        J("jldi j8, 0"); gl("j4", RTAB); J("jjz j4, %s" % empty)
        J("jldi j10, 1", "jshl j5, j2, j10", "jxor j5, j5, j1", "jldi j10, 3", "jshl j7, j3, j10", "jxor j5, j5, j7"); li("j10", GOLD)
        J("jmul j5, j5, j10", "jldi j10, 29", "jshr j5, j5, j10"); gl("j7", RTN); J("jldi j10, 1", "jsub j7, j7, j10")
        o("%s:" % tag)
        J("jand j5, j5, j7", "jldi j10, 5", "jshl j8, j5, j10", "jadd j8, j8, j4", "jld j10, j8, 24"); li("j11", UNK)
        J("jsub j11, j10, j11", "jjz j11, %s" % empty)
        for k, r in ((0, "j1"), (8, "j2"), (16, "j3")):
            J("jld j11, j8, %d" % k, "jsub j11, j11, %s" % r, "jjnz j11, %s_n" % tag)
        J("jjmp %s" % found)
        o("%s_n:" % tag)
        J("jldi j10, 1", "jadd j5, j5, j10", "jjmp %s" % tag)
    def fold():                         # j0 = a reading: the best so far (BEST, HAVE) takes it if it is one and better
        a = g["lab"]("fold")
        li("j10", UNK); J("jsub j10, j0, j10", "jjz j10, %s" % a); gl("j1", HAVE); J("jjz j1, %s_t" % a)
        gl("j1", BEST); J("jsub j1, j0, j1", "jjn j1, %s" % a, "jjz j1, %s" % a)
        o("%s_t:" % a); gs("j0", BEST); J("jldi j1, 1"); gs("j1", HAVE); J("jldi j1, 1"); gs("j1", T4)
        o("%s:" % a)
    def place(field):                   # the count of the place the thought came from (RJF): one more
        gl("j4", RJF); J("jldi j10, 4", "jshl j7, j4, j10"); li("j10", B + FT); J("jadd j7, j7, j10")
        J("jld j1, j7, %d" % field, "jldi j10, 1", "jadd j1, j1, j10", "jst j1, j7, %d" % field)
    def pwish():                        # j1 = the wish for the place at j7, as hers (uses j2, j10)
        J("jld j1, j7, 8", "jadd j1, j1, j1", "jldi j10, 1", "jadd j1, j1, j10", "jldi j10, 20", "jshl j1, j1, j10",
          "jld j2, j7, 0", "jldi j10, 1", "jadd j2, j2, j10", "jdiv j1, j1, j2")
    def go_on():                        # she goes on, resting or thinking, by her wishes for those two
        WA, WB = 8 * 16, 8 * 17
        gl("j1", WA); gl("j2", WB); J("jadd j1, j1, j2", "jcall r_randmod")
        gl("j1", WA); J("jsub j2, j0, j1", "jjn j2, fr_rest", "jjmp fr_think")

    TESTING = bool(os.environ.get("LUMA_PRUEBA_E"))
    TECHO = bool(os.environ.get("LUMA_TECHO"))
    ALEGRIA = bool(os.environ.get("LUMA_ALEGRIA"))
    UNICO = not TECHO and not ALEGRIA
    def rrec_zero():
        li("j7", B + RREC); J("jst j14, j7, 0", "jst j14, j7, 8", "jst j14, j7, 16", "jst j14, j7, 24")
    def rrec_form(reg):                 # the recipe to read: her form of that place
        form_addr("j9", reg); li("j7", B + RREC)
        for k in range(4):
            J("jld j10, j9, %d" % (F_REC + 8 * k), "jst j10, j7, %d" % (8 * k))
    def keyget():                       # the recipe to read -> its name (RLO, RHI), j0 = its reading with RGEN's instincts
        li("j9", B + RREC); J("jcall r_rec_key"); gs("j1", RLO); gs("j2", RHI); gl("j3", RGEN); J("jcall r_read_get")
    def known(lbl):                     # j0 is a reading -> lbl
        li("j10", UNK); J("jsub j10, j0, j10", "jjnz j10, %s" % lbl)
    def busca_routines():
        FNVO, FNVP = 0xCBF29CE484222325, 0x100000001B3
        assert LTAB + 8 * (NCELLS + 1) <= BU0 and 0x7FC0 + 24 <= DBUF
        def back(room):
            J("jldi j10, 3"); gl("j11", room); J("jldi j12, 0", "jcall r_tocar")
        def whole(room, size):
            J("jldi j10, 38", "jldi j11, -1", "jldi j12, 0", "jcall r_file"); gs("j13", size); J("jldi j10, 38", "jldi j11, 0", "jldi j12, 0", "jcall r_file")
            gl("j1", size); J("jldi j10, 64", "jadd j1, j1, j10", "jcall r_alloc"); gs("j0", room)
            J("jldi j10, 5"); gl("j11", room); gl("j12", size); J("jcall r_file", "jldi j10, 7", "jcall r_file")
        def qrec(reg, q):               # reg = the line of the question q (72 bytes: what this line of text has of it, the
            gl(reg, BQS); J("jldi j10, 72", "jmul j11, %s, j10" % q, "jadd %s, %s, j11" % (reg, reg))    # nearest, in how many places, its own words, ...)
        W_Q, W_C, W_T, W_R, W_RB, W_RL, W_CT, W_CL, W_P, W_A, W_N = (8 * i for i in range(11))
        WS, at = {}, 128                # her walks' words, in their room
        for k, t in (("ROD", b"rodeos"), ("CAM", b"caminos"), ("MIA", b"preguntas-mias"), ("ARR", b" -> "), ("BAR", b" | "),
                     ("COL", b": "), ("NL", b"\n"), ("SP", b" "), ("LOST", b" -> (no lleva a ningun lado)"),
                     ("BACK", b" -> volvi por otro camino: "), ("TROD", b"rodeando: de "), ("TA", b" a "),
                     ("TLOST", b"me perdi rodeando por "), ("TBACK", b"volvi a "), ("TBY", b" por otro camino: ")):
            WS[k] = (at, t); at += len(t)
        W_RECS = 512; assert at <= W_RECS
        def wl(r, off): gl("j6", BWR); J("jld %s, j6, %d" % (r, off))
        def wst(r, off): gl("j6", BWR); J("jst %s, j6, %d" % (r, off))
        def wa(r, off): gl(r, BWR); J("jldi j10, %d" % off, "jadd %s, %s, j10" % (r, r))
        def wrec(reg, q):               # reg = the walk of the question q (128 bytes: its door, where it comes from, ...)
            gl(reg, BWR); J("jldi j10, 128", "jmul j11, %s, j10" % q, "jadd %s, %s, j11" % (reg, reg), "jldi j10, %d" % W_RECS, "jadd %s, %s, j10" % (reg, reg))
        o("bw_letter:                      ; the character at j1 (before j2) -> j3 = its print if it is a letter, j1 past it; else")
        o("                                ; j3 = -1, j1 kept. A letter: a..z, small or capital alike, or any whole character past")
        o("                                ; ASCII (its print, its own code point: which of those are one, she learns). Uses j5, j6,")
        o("                                ; j10, j11")
        J("jldb j3, j1, 0", "jldi j10, 128", "jsub j10, j3, j10", "jjnn j10, bl_multi",
          "jldi j10, 32", "jor j3, j3, j10", "jldi j10, 97", "jsub j10, j3, j10", "jjn j10, bl_no", "jldi j10, 123", "jsub j10, j3, j10", "jjnn j10, bl_no",
          "jldi j10, 1", "jadd j1, j1, j10", "jret")
        o("bl_multi:                       ; (UTF-8: a first byte, and as many following ones as it says)")
        J("jldi j10, 194", "jsub j10, j3, j10", "jjn j10, bl_no",
          "jldi j10, 224", "jsub j10, j3, j10", "jjnn j10, bl_m3", "jldi j10, 31", "jand j3, j3, j10", "jldi j11, 1", "jjmp bl_c")
        o("bl_m3:")
        J("jldi j10, 240", "jsub j10, j3, j10", "jjnn j10, bl_m4", "jldi j10, 15", "jand j3, j3, j10", "jldi j11, 2", "jjmp bl_c")
        o("bl_m4:")
        J("jldi j10, 245", "jsub j10, j3, j10", "jjnn j10, bl_no", "jldi j10, 7", "jand j3, j3, j10", "jldi j11, 3")
        o("bl_c:")
        J("jadd j5, j1, j14")
        o("bl_cl:")
        J("jldi j10, 1", "jadd j1, j1, j10", "jsub j10, j1, j2", "jjnn j10, bl_back", "jldb j6, j1, 0", "jldi j10, 128", "jsub j6, j6, j10", "jjn j6, bl_back",
          "jldi j10, 64", "jsub j10, j6, j10", "jjnn j10, bl_back", "jldi j10, 6", "jshl j3, j3, j10", "jor j3, j3, j6",
          "jldi j10, 1", "jsub j11, j11, j10", "jjnz j11, bl_cl", "jadd j1, j1, j10", "jret")
        o("bl_back:")
        J("jadd j1, j5, j14")
        o("bl_no:")
        J("jldi j3, -1", "jret")
        o("bw_word:                        ; the next word of the line at BP (a run of letters, bw_letter) -> j0 = how many letters")
        o("                                ; (1 or more), j4 its print and BWS where it began, or j0 = 0 at the end of the line (BP on")
        o("                                ; it). Uses j1-j3, j5,")
        o("                                ; j6, j10, j11")
        gl("j1", BP); gl("j2", BE)
