        gl("j1", DT1); J("jldi j10, 3", "jshl j11, j1, j10"); li("j7", B + DNJ); J("jadd j7, j7, j11", "jld j9, j7, 0", "jldi j10, 20", "jshl j3, j3, j10", "jdiv j3, j3, j9"); gl("j4", DFW)
        J("jsub j10, j3, j4", "jjn j10, dg_s_m", "jadd j3, j4, j14")
