        gl("j0", DT1); J("jldi j10, 3", "jsub j10, j0, j10", "jjnz j10, dg_t_a"); gl("j5", DT2); J("jldi j10, 1", "jsub j10, j5, j10", "jjz j10, dg_t_e")
        o("dg_t_a:                         ; how many names more this line needs: no piece has more than sixteen")
